  (91, true, '91|||Therapy for teenagers, couples therapy and parenting guidance', '91|||פסיכותרפיה לילדים, לנוער, לזוגות ולהורים. במרפאה.', '{"org":"Hakshiva","svc":"פסיכותרפיה לילדים, לנוער, לזוגות ולהורים. במרפאה.","target":"ילדים, נוער, זוגות והורים","region":"רמת בית שמש","cost":"","specialty":"חרדה, דיכאון, טראומה","approaches":"טיפול ממוקד תובנה, CBT, טיפול משפחתי","languages":"עברית, אנגלית","diseases":"","notes":"גם חונכות, מרכז נוער, וסיוע לימודי. המרכז בנחל שורק 14, רמת בית שמש.","meeting":"in_person","web":"https://hakshiva.org/","add":"","addLabel":"","whatsapp":"02-992-5152","phone":"02-992-5152","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Hakshiva","svc":"Psychotherapy for children, for youth, for couples, and for parents. At the clinic.","target":"Children, youth, couples, and parents","region":"Ramat Beit Shemesh","specialty":"Anxiety, depression, trauma","approaches":"Insight-oriented therapy, CBT, family therapy","languages":"Hebrew, English","notes":"Also mentoring, a youth center, and learning support. The center is at 14 Nahal Sorek, Ramat Beit Shemesh.","meeting":"in_person","phone":"02-992-5152","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","whatsapp":"02-992-5152"}'::jsonb, '27.11.2026: עמוד הקליניקה הישן החזיר 404. נבדק מול https://hakshiva.org/. פסיכולוגים ועובדים סוציאליים, בלי אזכור של תרופות. וואטסאפ במספר הטלפון. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (92, true, '92|||דיכאון אחרי לידה ועוד, דרך טיפת חלב בירושלים
Support and treatment for Maternal Mental Health through Tipat Halav. Services for mothers and families impacted by perinatal mental health disorders (PMHD) such as postpartum depression', '92|||פסיכותרפיה קצרה בבית, לאימהות עם דיכאון סב-לידתי. בבית.', '{"org":"חבלי קשר","svc":"פסיכותרפיה קצרה בבית, לאימהות עם דיכאון סב-לידתי. בבית.","target":"אימהות ומשפחות","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"עברית, אנגלית","diseases":"","notes":"גם הכשרה לאנשי מקצוע.","meeting":"in_person","web":"https://hevleikesher.org/he/%D7%97%D7%91%D7%9C%D7%99-%D7%A7%D7%A9%D7%A8-%D7%93%D7%A3-%D7%94%D7%91%D7%99%D7%AA/","webLabel":"עברית","web2":"https://hevleikesher.org/","webLabel2":"English","add":"","addLabel":"","phone":"052-603-9181","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"contact@hevleikesher.org","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Hevlei Kesher","svc":"Short-term psychotherapy at home, for mothers with perinatal depression. At home.","target":"Mothers and families","region":"Nationwide","languages":"Hebrew, English","notes":"Also training for health professionals.","meeting":"in_person","webLabel":"Hebrew","webLabel2":"English","phone":"052-603-9181","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"contact@hevleikesher.org","emailLabel":"Email"}'::jsonb, '27.11.2026: נבדק מול האתר בעברית ובאנגלית. טיפול קצר בבית על ידי עובדת סוציאלית קלינית. עמוד העירייה כבר אינו מתאר את השירות, והקישור אליו ירד. טיפת חלב וירושלים בלבד לא עלו. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (93, true, '93|||CBT, DBT, and Exposure-Based Therapies', '93|||פסיכותרפיה פרטית. במרפאה.', '{"org":"Modi''in Behavioral","svc":"פסיכותרפיה פרטית. במרפאה.","target":"מבוגרים","region":"מודיעין","founded":"2018","cost":"פרטי","specialty":"חרדה, דיכאון, OCD, PTSD, הפרעת אישיות גבולית","approaches":"CBT, DBT, חשיפה","languages":"","diseases":"","notes":"גם פוביות, כעס, קשיים בקשר, והסתגלות ללימודים. בניין רקיע, דם המכבים 36.","meeting":"in_person","web":"https://www.modiinbehavioral.com/","phone":"053-304-8701","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"steven.schlager@gmail.com","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Modi''in Behavioral","svc":"Private psychotherapy. At the clinic.","target":"Adults","region":"Modiin","founded":"2018","cost":"Private","specialty":"Anxiety, depression, OCD, PTSD, borderline personality disorder","approaches":"CBT, DBT, exposure","notes":"Also phobias, anger, relationship difficulties, and adjusting to studies. Rakia building, 36 Dam HaMaccabim.","meeting":"in_person","phone":"053-304-8701","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"steven.schlager@gmail.com","emailLabel":"Email"}'::jsonb, '27.11.2026: נבדק מול https://www.modiinbehavioral.com/. הוקם 2018. אין אזכור של זום. בניין רקיע, דם המכבים 36. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (80, false, '80|||Clinical case management for English-speakers in Israel from all walks of life: counseling, referrals to therapists, treatment programs, guidance through the legal process', '80|||ליווי במצבי משבר: בריאות הנפש, טראומה והתמכרות.', '{"org":"Amudim","svc":"ליווי במצבי משבר: בריאות הנפש, טראומה והתמכרות.","target":"מי שנמצא במשבר","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"המשרד בנתן שטראוס 3, ירושלים.","meeting":"","web":"https://amudim.org.il/","phone":"02-374-0175","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"office@amudim.org.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Amudim","svc":"Support in a crisis: mental health, trauma, and addiction.","target":"A person in a crisis","region":"Nationwide","notes":"The office is at 3 Natan Strauss, Jerusalem.","phone":"02-374-0175","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"office@amudim.org.il","emailLabel":"Email"}'::jsonb, '27.11.2026: נבדק מול https://amudim.org.il/. העמוד אינו מגביל את השירות לדוברי אנגלית, ואינו מתאר ניהול תיק קליני. המספר בארצות הברית לא עלה. מאוחדת באותה שורה לא נגעה. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (242, true, '242|||קו סיוע וקישורים — להט"ב, הורים, דתיים, נוער', '242|||קו קשב, מידע ותמיכה לקהילה הגאה ולבני משפחה. בטלפון או בוואטסאפ.', '{"org":"האגודה למען הלהט״ב","svc":"קו קשב, מידע ותמיכה לקהילה הגאה ולבני משפחה. בטלפון או בוואטסאפ.","target":"חברי הקהילה הגאה ובני משפחה","region":"כל הארץ","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"אפשר בעילום שם. גם וואטסאפ בערבית, 054-873-2110. תהל״ה ואיגי הם ארגונים נפרדים.","meeting":"","tags":"חרבות ברזל","web":"https://www.lgbt.org.il/communityservices","whatsapp":"058-620-5591","phone":"*2982","phoneLabel":"עברית ואנגלית","phoneShowNumber":false,"phone2":"077-546-6359","phoneLabel2":"ערבית","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"yesh@lgbt.org.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"The Aguda","svc":"A listening line, information, and support for the LGBTQ community and for family members. By phone or on WhatsApp.","target":"LGBTQ community members and family members","region":"Nationwide","cost":"At no cost","notes":"A caller can stay anonymous. Also a WhatsApp line in Arabic, 054-873-2110. Tehila and IGY are separate organizations.","phone":"*2982","phoneLabel":"Hebrew and English","phone2":"077-546-6359","phoneLabel2":"Arabic","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"yesh@lgbt.org.il","emailLabel":"Email","whatsapp":"058-620-5591"}'::jsonb, '27.11.2026: נבדק מול https://www.lgbt.org.il/communityservices. הקו המפורסם הוא *2982, וואטסאפ 058-620-5591, וקו בערבית. 03-6205591 לא עלה. השעות לא עלו. תגית חרבות ברזל נשארה. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (260, true, '260|||הסברה וסדנאות בבתי ספר ובמסגרות נוער למניעת להט"בופוביה ולתמיכה בנוער להט"ב', '260|||סדנאות הסברה בבתי ספר, למניעת להט״בופוביה. בבית הספר.', '{"org":"חוש״ן","svc":"סדנאות הסברה בבתי ספר, למניעת להט״בופוביה. בבית הספר.","target":"תלמידים וצוותי חינוך","region":"כל הארץ","founded":"2004","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"גם לצוותים טיפוליים ולכוחות הביטחון. המשרד בדב הוז 25, תל אביב.","meeting":"in_person","web":"https://www.hoshen.org/","phone":"03-6033373","phoneLabel":"משרד","phoneShowNumber":false,"phone2":"052-5603000","phoneLabel2":"הזמנת פעילויות","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"office@hoshen.org","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Hoshen","svc":"Education workshops in schools, to prevent LGBTQ-phobia. At the school.","target":"Students and education staff","region":"Nationwide","founded":"2004","notes":"Also for treatment teams and for the security forces. The office is at 25 Dov Hoz, Tel Aviv.","meeting":"in_person","phone":"03-6033373","phoneLabel":"Office","phone2":"052-5603000","phoneLabel2":"Booking activities","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"office@hoshen.org","emailLabel":"Email"}'::jsonb, '27.11.2026: נבדק מול https://www.hoshen.org/ ועמוד יצירת הקשר. הוקמה ב-2004. דב הוז 25, תל אביב. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (265, true, '265|||ליווי ילדים ובוגרים על הרצף האוטיסטי ומשפחותיהם — זכויות, מרכזי משפחה ותמיכה', '265|||ליווי ילדים, בוגרים ומשפחות על הרצף האוטיסטי, מרגע האבחון. בקהילה או בטלפון.', '{"org":"אלו״ט","svc":"ליווי ילדים, בוגרים ומשפחות על הרצף האוטיסטי, מרגע האבחון. בקהילה או בטלפון.","target":"ילדים, בוגרים ומשפחות על הרצף האוטיסטי","region":"כל הארץ","founded":"1974","cost":"קווי הסיוע ללא עלות. התוכניות למשפחה במחיר מסובסד.","specialty":"","approaches":"","languages":"","diseases":"","notes":"המשרד בכורזין 1, גבעתיים. להרשמה לתוכניות המשפחה גם בוואטסאפ.","meeting":"in_person","web":"https://alut.org.il/","whatsapp":"03-5115001","phone":"03-5718188","phoneLabel":"משרד","phoneShowNumber":false,"phone2":"*5922","phoneLabel2":"מיצוי זכויות","phoneShowNumber2":false,"phone3":"03-6709094","phoneLabel3":"תמיכה להורים","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"info@alut.org.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"ALUT","svc":"Accompaniment for children, adults, and families on the autism spectrum, from the diagnosis. In the community or by phone.","target":"Children, adults, and families on the autism spectrum","region":"Nationwide","founded":"1974","cost":"The support lines are at no cost. The family programs are at a subsidized price.","notes":"The office is at 1 Korazin, Givatayim. Registration for the family programs is also on WhatsApp.","meeting":"in_person","phone":"03-5718188","phoneLabel":"Office","phone2":"*5922","phoneLabel2":"Rights","phone3":"03-6709094","phoneLabel3":"Parent support","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"info@alut.org.il","emailLabel":"Email","whatsapp":"03-5115001"}'::jsonb, '27.11.2026: נבדק מול https://alut.org.il/, עמוד יצירת הקשר ועמוד אלוט למשפחה. הוקמה ב-1974. *5922 למיצוי זכויות, 03-6709094 תמיכה מהורים להורים, וואטסאפ 03-5115001 להרשמה. השעות לא עלו. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (276, true, '276|||ייעוץ הלכתי ורוחני למתמודדים ולבני משפחה — רבנים ורבניות שעברו הכשרה בבריאות הנפש (לא טיפול קליני)', '276|||ייעוץ הלכתי ורוחני למתמודדים ולבני משפחה. בזום, בטלפון או במייל.', '{"org":"מעגלי נפש","svc":"ייעוץ הלכתי ורוחני למתמודדים ולבני משפחה. בזום, בטלפון או במייל.","target":"מתמודדים ובני משפחה","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"עברית, אנגלית","diseases":"","notes":"מפגש של כחצי שעה. גם הכשרת רבנים ומנהיגי קהילה.","meeting":"online","web":"https://mnefesh.org/he/","webLabel":"עברית","web2":"https://mnefesh.org/","webLabel2":"English","add":"https://www.facebook.com/mnefesh","addLabel":"פייסבוק","phone":"02-372-4448","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"support@mnefesh.org","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Maagalei Nefesh","svc":"Halachic and spiritual counsel for people coping with mental illness and for family members. On Zoom, by phone, or by email.","target":"People coping with mental illness, and family members","region":"Nationwide","languages":"Hebrew, English","notes":"A meeting of about half an hour. Also training for rabbis and community leaders.","meeting":"online","webLabel":"Hebrew","webLabel2":"English","addLabel":"Facebook","phone":"02-372-4448","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"support@mnefesh.org","emailLabel":"Email"}'::jsonb, '27.11.2026: נבדק מול https://mnefesh.org/he/ ועמוד קביעת השיחה. support@mnefesh.org. מפגש של כחצי שעה בזום, בטלפון או במייל. המשפט שזה אינו קו חירום לא עלה לכרטיס. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (87, true, '87|||מומחית בהפרעות אכילה/תזונה/כושר/דיאטה, מטפלת בפגועי נפש עם רישיון. בעלות סימלית, חברות ביטוח מחזירות', '87|||ייעוץ תזונתי קליני, כולל הפרעות אכילה. בקליניקה או בשיחת וידאו.', '{"org":"ענת אופיר מטיאש","svc":"ייעוץ תזונתי קליני, כולל הפרעות אכילה. בקליניקה או בשיחת וידאו.","target":"ילדים, נוער ומבוגרים","region":"גבעת שמואל, תל אביב, מודיעין","cost":"","specialty":"הפרעות אכילה","approaches":"","languages":"","diseases":"","notes":"גם עד הבית. גבעת שמואל: ירושלים 6. תל אביב: עיר שמש 17. מודיעין: דם המכבים 38.","meeting":"in_person","web":"https://www.fiteat.com","phone":"054-2224646","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"Anatmatiash@gmail.com","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Anat Ofir Matiash","svc":"Clinical nutrition counseling, including eating disorders. At the clinic or by video.","target":"Children, youth, and adults","region":"Givat Shmuel, Tel Aviv, Modiin","specialty":"Eating disorders","notes":"Also home visits. Givat Shmuel: 6 Jerusalem. Tel Aviv: 17 Ir Shemesh. Modiin: 38 Dam HaMaccabim.","meeting":"in_person","phone":"054-2224646","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"Anatmatiash@gmail.com","emailLabel":"Email"}'::jsonb, '27.11.2026: נבדק מול https://www.fiteat.com. קליניקות בגבעת שמואל, בתל אביב ובמודיעין, וגם שיחת וידאו ועד הבית. אין מחירון בעמוד. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (204, true, '204|||נטורופתיה קלינית — איזון גוף–נפש (כאבים, עייפות, סטרס, עיכול, אכילה רגשית ועוד); קליניקה ומפגשים מקוונים.', '204|||נטורופתיה ותזונה הוליסטית. בקליניקה.', '{"org":"אדווה ליזר","svc":"נטורופתיה ותזונה הוליסטית. בקליניקה.","target":"","region":"נתניה","cost":"","specialty":"","approaches":"נטורופתיה, תזונה הוליסטית","languages":"","diseases":"","notes":"ברוש 5, נתניה. גם פרחי באך, NLP ודמיון מודרך.","meeting":"in_person","web":"https://adva-lieser.co.il","whatsapp":"","whatsappLabel":"","phone":"054-6414863","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"forevergenyoung@gmail.com","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Adva Lieser","svc":"Naturopathy and holistic nutrition. At the clinic.","region":"Netanya","approaches":"Naturopathy, holistic nutrition","notes":"5 Brosh, Netanya. Also Bach flowers, NLP, and guided imagery.","meeting":"in_person","phone":"054-6414863","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"forevergenyoung@gmail.com","emailLabel":"Email"}'::jsonb, '27.11.2026: נבדק מול https://adva-lieser.co.il. הקליניקה בברוש 5, נתניה. העמוד אינו מתאר מפגש מקוון או פריסה ארצית, ואינו מפרסם וואטסאפ. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (264, true, '264|||מידע לציבור ולמשפחות, מפת מסגרות טיפול ואינדקס מטפלים בהפרעות אכילה', '264|||מידע על הפרעות אכילה, רשימת מרכזי טיפול, ואינדקס מטפלים.', '{"org":"העמותה הישראלית למניעה, טיפול ומחקר בהפרעות אכילה","svc":"מידע על הפרעות אכילה, רשימת מרכזי טיפול, ואינדקס מטפלים.","target":"","region":"כל הארץ","cost":"","specialty":"הפרעות אכילה","approaches":"","languages":"","diseases":"","notes":"העמותה עצמה אינה נותנת טיפול. הפנייה היא למרכז או למטפל שבאתר.","meeting":"","web":"https://www.iaed.org.il/","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"israel.aed@gmail.com","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"The Israeli Association for the Prevention, Treatment and Research of Eating Disorders","svc":"Information on eating disorders, a list of treatment centers, and an index of therapists.","region":"Nationwide","specialty":"Eating disorders","notes":"The association itself does not provide treatment. The referral is to a center or a therapist on the site.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"israel.aed@gmail.com","emailLabel":"Email"}'::jsonb, '27.11.2026: נבדק מול https://www.iaed.org.il/ ועמוד יצירת הקשר. אין טלפון. העמותה מפנה למרכזים ולאינדקס, ואינה נותנת טיפול בעצמה. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (83, false, '83|||הסעות חולים, אמבולנסים לצרכים רפואיים ואירועים משפחתיים, נהגים מתנדבים', '83|||הסעות באמבולנס וברכב מונגש, וגם הסעות עם נהגים מתנדבים. בתיאום.', '{"org":"עזר מציון","svc":"הסעות באמבולנס וברכב מונגש, וגם הסעות עם נהגים מתנדבים. בתיאום.","target":"חולים ומוגבלי תנועה","region":"כל הארץ","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"לאמבולנס מתקשרים יום לפני, עד 12:00. נדרש מלווה. לא לנסיעת חירום. הסעות המתנדבים לחולים כרוניים פועלות בירושלים, בבני ברק ובפתח תקווה, והטלפון של כל סניף באתר.","meeting":"","web":"https://www.ami.org.il/services/ambulances","phone":"03-6144666","phoneLabel":"אמבולנס","phoneShowNumber":false,"phone2":"073-2477777","phoneLabel2":"מתנדבים","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Ezer Mizion","svc":"Rides by ambulance and by an accessible vehicle, and also rides with volunteer drivers. By arrangement.","target":"Patients and people with limited mobility","region":"Nationwide","cost":"At no cost","notes":"For an ambulance, call the day before, by 12:00. A companion is required. Not for an emergency ride. Volunteer rides for people with a chronic illness run in Jerusalem, Bnei Brak, and Petah Tikva, and each branch phone is on the site.","phone":"03-6144666","phoneLabel":"Ambulance","phone2":"073-2477777","phoneLabel2":"Volunteers","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '27.11.2026: נבדק מול עמוד האמבולנסים ועמוד הסעות החולים באתר עזר מציון. 03-6144666 ו-073-2477777. קו התרומות והמרכזייה לא עלו. כל זכות באותה שורה לא נגעה. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (84, false, '84|||סיוע באמבולנסים בהעברת חולים ונכים', '84|||הסעות באמבולנס לחולים ולנכים, גם לשדה התעופה. בתיאום.', '{"org":"לב מלכה","svc":"הסעות באמבולנס לחולים ולנכים, גם לשדה התעופה. בתיאום.","target":"חולים ונכים","region":"כל הארץ","founded":"1992","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"המשרד בהמ״ג 38, ירושלים. גם מחנות נופש והגשמת משאלות לילדים חולים.","meeting":"","web":"https://levmalka.org.il/%D7%AA%D7%97%D7%95%D7%9E%D7%99-%D7%A2%D7%A9%D7%99%D7%99%D7%94/","phone":"02-5376666","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"m662@levmalka.org.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Lev Malka","svc":"Ambulance rides for patients and for people with a disability, including to the airport. By arrangement.","target":"Patients and people with a disability","region":"Nationwide","founded":"1992","cost":"At no cost","notes":"The office is at 38 HaMem Gimel, Jerusalem. Also holiday camps and granted wishes for children who are ill.","phone":"02-5376666","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"m662@levmalka.org.il","emailLabel":"Email"}'::jsonb, '27.11.2026: נבדק מול עמוד תחומי העשייה באתר לב מלכה. הנסיעות ללא תשלום, כולל לשדה התעופה. הוקם 1992. כל זכות באותה שורה לא נגעה. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (245, true, '245|||שירותי אמבולנס ללא תשלום להסעת חולים, נכים ומוגבלים לטיפולים, בדיקות ושמחות', '245|||הסעות באמבולנס לחולים, לנכים ולמוגבלי תנועה. בתיאום.', '{"org":"רפואה ושמחה","svc":"הסעות באמבולנס לחולים, לנכים ולמוגבלי תנועה. בתיאום.","target":"חולים, נכים ומוגבלי תנועה","region":"כל הארץ","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"להזמין יום לפני, עד 12:00. נדרש מלווה. לא למקרי חירום. המשרד בהרטום 9, ירושלים.","meeting":"","web":"https://refuavesimcha.co.il/free-ambulance/","phone":"02-800-2000","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Refua VeSimcha","svc":"Ambulance rides for patients, for people with a disability, and for people with limited mobility. By arrangement.","target":"Patients, people with a disability, and people with limited mobility","region":"Nationwide","cost":"At no cost","notes":"Book the day before, by 12:00. A companion is required. Not for an emergency. The office is at 9 Hartom, Jerusalem.","phone":"02-800-2000","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '27.11.2026: נבדק מול https://refuavesimcha.co.il/free-ambulance/. ללא עלות. הרטום 9, ירושלים. העמוד מזכיר וואטסאפ בלי מספר, ולכן אין כפתור. הפקס לא עלה. השעות לא עלו. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (246, true, '246|||שירותי אמבולנס להסעת חולים, נכים ומוגבלים לטיפולים, בדיקות ואירועים משפחתיים', '246|||הסעות באמבולנס לחולים, לנכים ולמוגבלי תנועה. בתיאום.', '{"org":"עזרה למרפא","svc":"הסעות באמבולנס לחולים, לנכים ולמוגבלי תנועה. בתיאום.","target":"חולים, נכים ומוגבלי תנועה","region":"כל הארץ","cost":"במימון תורמי העמותה","specialty":"","approaches":"","languages":"","diseases":"","notes":"נדרש מלווה. אחרי אשפוז צריך מכתב שחרור. המרכז בחיד״א 24, בני ברק.","meeting":"","web":"https://www.ezra-lemarpe.org/ambulances/","phone":"03-5777000","phoneLabel":"מרכז ודרום, שלוחה 5","phoneShowNumber":false,"phone2":"1599-51-51-61","phoneLabel2":"מוקד ארצי","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Ezra Lemarpe","svc":"Ambulance rides for patients, for people with a disability, and for people with limited mobility. By arrangement.","target":"Patients, people with a disability, and people with limited mobility","region":"Nationwide","cost":"Funded by the association donors","notes":"A companion is required. After a hospitalization, a discharge letter is required. The center is at 24 Hida, Bnei Brak.","phone":"03-5777000","phoneLabel":"Center and south, extension 5","phone2":"1599-51-51-61","phoneLabel2":"National line","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '27.11.2026: נבדק מול https://www.ezra-lemarpe.org/ambulances/. 03-5777000 שלוחה 5, ו-1599-51-51-61. מספרי הסניפים והמספר בארצות הברית לא עלו. השעות לא עלו. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.'),
  (295, true, '295|||הסעות מסובסדות לבתי חולים מבית שמש לירושלים, אמבולנסים ורכבים מונגשים', '295|||הסעות מסובסדות לבתי חולים, וגם אמבולנס ורכבים מונגשים. בתיאום.', '{"org":"עזרת אחים","svc":"הסעות מסובסדות לבתי חולים, וגם אמבולנס ורכבים מונגשים. בתיאום.","target":"חולים, קשישים, נכים ויולדות","region":"בית שמש והסביבה","cost":"מסובסד","specialty":"","approaches":"","languages":"","diseases":"","notes":"ההסעות לבתי החולים הן מבית שמש לירושלים. גם באזורים אחרים, לפי זמינות. גם אמבולנס שבת ליולדות. לתאם לפחות יום מראש. המשרד בהנביא עמוס 1, בית שמש.","meeting":"","web":"https://eza.org.il/activities-domain/transportation/","web2":"https://eza.org.il/our-activities/%D7%94%D7%A1%D7%A2%D7%95%D7%AA-%D7%97%D7%95%D7%9C%D7%99%D7%9D/","webLabel2":"הסעות חולים","phone":"1800-999-000","phoneLabel":"הסעות, שלוחה 1","phoneShowNumber":false,"phone2":"*2348","phoneLabel2":"מסלולים","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Ezrat Achim","svc":"Subsidized rides to hospitals, and also an ambulance and accessible vehicles. By arrangement.","target":"Patients, older people, people with a disability, and women in labor","region":"Beit Shemesh and the surrounding area","cost":"Subsidized","notes":"The hospital rides run from Beit Shemesh to Jerusalem. Also in other areas, when a vehicle is available. Also a Shabbat ambulance for women in labor. Book at least a day ahead. The office is at 1 HaNavi Amos, Beit Shemesh.","webLabel2":"Patient rides","phone":"1800-999-000","phoneLabel":"Rides, extension 1","phone2":"*2348","phoneLabel2":"Routes","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '27.11.2026: נבדק מול עמוד תחום ההסעות ועמוד הסעות החולים באתר עזרת אחים. 1800-999-000 שלוחה 1, ו-*2348 למסלולים. השעות לא עלו. הניסוח אושר עם אצוות השירותים המקומיים, האוכלוסיות, התזונה וההסעות.');

UPDATE site_audit_entries s
SET card_keys = (
  SELECT COALESCE(array_agg(
    COALESCE((SELECT w.new_key FROM local_wording w WHERE w.old_key = k), k)
    ORDER BY ord
  ), '{}')
  FROM unnest(s.card_keys) WITH ORDINALITY AS u(k, ord)
)
WHERE EXISTS (
  SELECT 1
  FROM unnest(s.card_keys) k
  JOIN local_wording w ON w.old_key = k
);

UPDATE directory_card_edits c
SET card_key = w.new_key,
    public_fields = COALESCE(c.public_fields, '{}'::jsonb) || w.fields,
    translations = jsonb_set(
      COALESCE(c.translations, '{}'::jsonb),
      '{en}',
      COALESCE(c.translations->'en', '{}'::jsonb) || w.en,
      true
    ),
    eligibility = jsonb_set(
      COALESCE(c.eligibility, '{}'::jsonb),
      '{internal_notes}',
      to_jsonb(
        CASE
          WHEN COALESCE(c.eligibility->>'internal_notes', '') = '' THEN w.note
          ELSE rtrim(c.eligibility->>'internal_notes') || E'\n\n' || w.note
        END
      ),
      true
    ),
    public_edited_at = now(),
    updated_at = now()
FROM local_wording w
WHERE c.card_key = w.old_key
   OR (
     w.unique_row
     AND c.row_id = w.row_id
     AND (SELECT count(*) FROM directory_card_edits d WHERE d.row_id = w.row_id) = 1
   );

UPDATE directory_entries e
SET display_name = c.public_fields->>'org',
    description = c.public_fields->>'svc'
FROM directory_card_edits c
JOIN local_wording w ON w.new_key = c.card_key
WHERE e.entry_id = c.entry_id;

COMMIT;
